package com.dekhocampus.platform.api;
import jakarta.servlet.http.HttpServletRequest; import java.util.Set; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.client.RestClient; import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/v1/functions") public class FunctionCompatibilityController {
 private static final Set<String> ALLOWED=Set.of("admin-ai-generate","admin-blog-agent","admin-blog-ai-settings","admin-blog-studio","admin-data-cleaner","admin-invite-user","ai-counselor","cat-response-analyzer","check-eligibility","dispatch-intent-alert","google-reviews","intent-export-csv","lp-dispatch-lead","lp-multi-push","lp-process-batch","lp-receive-lead","lp-test-api","lp-utm","phone-auth","predict-colleges","predict-lead-intent","process-lead","process-queue","purge-university-cache","push-receive-lead","receive-lead","save-lead","send-email","send-otp","study-otp","summarize-user-session","target-roadmap","test-api","url-redirect");
 private final String url,key; private final RestClient client=RestClient.create();
 public FunctionCompatibilityController(@Value("${app.supabase-url}")String url,@Value("${app.supabase-publishable-key}")String key){this.url=url.replaceAll("/$","");this.key=key;}
 @PostMapping("/{name}") ResponseEntity<byte[]> invoke(@PathVariable String name,@RequestBody(required=false) byte[] body,HttpServletRequest request){if(!ALLOWED.contains(name))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Unknown function");if(url.isBlank()||key.isBlank())throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Supabase compatibility bridge is not configured");var call=client.post().uri(url+"/functions/v1/"+name).header("apikey",key).contentType(MediaType.APPLICATION_JSON);var bearer=request.getHeader(HttpHeaders.AUTHORIZATION);if(bearer!=null)call.header(HttpHeaders.AUTHORIZATION,bearer);return call.body(body==null?new byte[0]:body).retrieve().toEntity(byte[].class);}
}
